prog='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])

    def combine(A, B):
        ca = Counter(x for r in A for x in r)
        cb = Counter(x for r in B for x in r)
        shared = max(set(ca) & set(cb), key=lambda x: ca[x] + cb[x])
        return [[3 if a == b else shared for a, b in zip(ra, rb)] for ra, rb in zip(A, B)]

    # column separator
    for c in range(w):
        col = [r[c] for r in grid]
        if len(set(col)) == 1 and col[0] != 0:
            A = [r[:c] for r in grid]; B = [r[c+1:] for r in grid]
            if A and B and all(len(ra) == len(rb) for ra, rb in zip(A, B)):
                return combine(A, B)
    # row separator
    for r0 in range(h):
        row = grid[r0]
        if len(set(row)) == 1 and row[0] != 0:
            A = grid[:r0]; B = grid[r0+1:]
            if A and B and len(A[0]) == len(B[0]):
                return combine(A, B)
    return grid
'''
